"""SQLite-backed inventory reservation service."""

from datetime import datetime, timezone

from src.db import get_connection
from src.exceptions import (
    InsufficientStockError,
    InvalidReservationError,
    ReservationNotFoundError,
    SkuNotFoundError,
)


def _validate_reservation_id(reservation_id: str) -> str:
    if not isinstance(reservation_id, str) or not reservation_id.strip():
        raise InvalidReservationError("reservation_id must be a non-empty string")
    return reservation_id.strip()


def get_available(db_path: str, sku: str) -> int:
    """Return available inventory quantity for SKU."""
    conn = get_connection(db_path)
    try:
        row = conn.execute("SELECT available_quantity FROM inventory WHERE sku = ?", (sku,)).fetchone()
        if row is None:
            raise SkuNotFoundError(f"SKU {sku} not found")
        return int(row["available_quantity"])
    finally:
        conn.close()


def reserve(db_path: str, reservation_id: str, sku: str, quantity: int) -> dict:
    """Reserve stock atomically; repeated identical active requests are idempotent."""
    reservation_id = _validate_reservation_id(reservation_id)
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
        raise InvalidReservationError("quantity must be a positive integer")

    conn = get_connection(db_path)
    try:
        # Acquire SQLite's write lock before checking state, serializing competing writers.
        conn.execute("BEGIN IMMEDIATE")

        existing = conn.execute(
            "SELECT sku, quantity, status FROM reservations WHERE reservation_id = ?",
            (reservation_id,),
        ).fetchone()
        if existing is not None:
            if existing["sku"] != sku or existing["quantity"] != quantity:
                raise InvalidReservationError("reservation_id already exists with different parameters")
            if existing["status"] != "active":
                raise InvalidReservationError("a cancelled reservation cannot be reopened")
            conn.execute("COMMIT")
            return {
                "reservation_id": reservation_id,
                "sku": existing["sku"],
                "quantity": existing["quantity"],
                "status": existing["status"],
            }

        cursor = conn.execute(
            """
            UPDATE inventory
            SET available_quantity = available_quantity - ?
            WHERE sku = ? AND available_quantity >= ?
            """,
            (quantity, sku, quantity),
        )
        if cursor.rowcount == 0:
            row = conn.execute(
                "SELECT available_quantity FROM inventory WHERE sku = ?", (sku,)
            ).fetchone()
            if row is None:
                raise SkuNotFoundError(f"SKU {sku} not found")
            raise InsufficientStockError(
                f"Requested {quantity}, available {row['available_quantity']}"
            )

        now_iso = datetime.now(timezone.utc).isoformat()
        conn.execute(
            """
            INSERT INTO reservations (reservation_id, sku, quantity, status, created_at, updated_at)
            VALUES (?, ?, ?, 'active', ?, ?)
            """,
            (reservation_id, sku, quantity, now_iso, now_iso),
        )
        conn.execute("COMMIT")
        return {
            "reservation_id": reservation_id,
            "sku": sku,
            "quantity": quantity,
            "status": "active",
        }
    except BaseException:
        if conn.in_transaction:
            conn.execute("ROLLBACK")
        raise
    finally:
        conn.close()


def cancel(db_path: str, reservation_id: str) -> dict:
    """Cancel a reservation and restore its stock at most once."""
    reservation_id = _validate_reservation_id(reservation_id)

    conn = get_connection(db_path)
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT sku, quantity, status FROM reservations WHERE reservation_id = ?",
            (reservation_id,),
        ).fetchone()
        if row is None:
            raise ReservationNotFoundError(f"Reservation {reservation_id} not found")

        sku = row["sku"]
        quantity = row["quantity"]
        if row["status"] == "active":
            cursor = conn.execute(
                "UPDATE inventory SET available_quantity = available_quantity + ? WHERE sku = ?",
                (quantity, sku),
            )
            if cursor.rowcount != 1:
                raise SkuNotFoundError(f"SKU {sku} not found")
            conn.execute(
                "UPDATE reservations SET status = 'cancelled', updated_at = ? "
                "WHERE reservation_id = ? AND status = 'active'",
                (datetime.now(timezone.utc).isoformat(), reservation_id),
            )
        elif row["status"] != "cancelled":
            raise InvalidReservationError("reservation has an invalid status")

        conn.execute("COMMIT")
        return {
            "reservation_id": reservation_id,
            "sku": sku,
            "quantity": quantity,
            "status": "cancelled",
        }
    except BaseException:
        if conn.in_transaction:
            conn.execute("ROLLBACK")
        raise
    finally:
        conn.close()

