import multiprocessing as mp
import os
import tempfile
from src.db import init_db, seed_inventory
from src.exceptions import InsufficientStockError, InvalidReservationError
from src.reservations import cancel, get_available, reserve


def reserve_worker(args):
    path, idx, q = args
    try:
        reserve(path, f'process-{idx}', 'SKU', 1)
        q.put('ok')
    except InsufficientStockError:
        q.put('short')
    except Exception as exc:
        q.put(f'error:{type(exc).__name__}:{exc}')


ctx = mp.get_context('fork')
with tempfile.TemporaryDirectory() as tmp:
    path = os.path.join(tmp, 'inventory.db')
    init_db(path)
    seed_inventory(path, {'SKU': 10})
    queue = ctx.Queue()
    procs = [ctx.Process(target=reserve_worker, args=((path, i, queue),)) for i in range(30)]
    for proc in procs:
        proc.start()
    for proc in procs:
        proc.join(30)
        assert proc.exitcode == 0, proc.exitcode
    results = [queue.get(timeout=2) for _ in procs]
    assert results.count('ok') == 10, results
    assert results.count('short') == 20, results
    assert not [result for result in results if result.startswith('error:')], results
    assert get_available(path, 'SKU') == 0

    for index, value in enumerate((True, False, 1.0, '2', 0, -1)):
        try:
            reserve(path, f'invalid-{index}', 'SKU', value)
        except InvalidReservationError:
            pass
        else:
            raise AssertionError(f'accepted invalid quantity {value!r}')
    try:
        reserve(path, '   ', 'SKU', 1)
    except InvalidReservationError:
        pass
    else:
        raise AssertionError('accepted blank reservation ID')
    try:
        reserve(path, 'process-0', 'SKU', 2)
    except InvalidReservationError:
        pass
    else:
        raise AssertionError('accepted conflicting reservation replay')
    cancel(path, 'process-0')
    try:
        reserve(path, 'process-0', 'SKU', 1)
    except InvalidReservationError:
        pass
    else:
        raise AssertionError('reopened a cancelled reservation')
    assert get_available(path, 'SKU') == 1
print('Focused process-concurrency and validation checks passed.')
